<script setup lang="ts">
import { Minus, Plus, ShoppingBag, Trash2 } from 'lucide-vue-next'
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import EmptyState from '@/components/ui/EmptyState.vue'
import ExportButtons from '@/components/ui/ExportButtons.vue'
import { ordersService } from '@/services/orders.service'
import { useAuthStore } from '@/stores/auth.store'
import { useCartStore } from '@/stores/cart.store'
import { useToastStore } from '@/stores/toast.store'
import { formatCurrency, getErrorMessage } from '@/utils/formatters'
const cart = useCartStore(); const auth = useAuthStore(); const toast = useToastStore(); const router = useRouter(); const busy = ref(false)
const exportRows = computed(() => cart.items.map((item) => [item.producto.id, item.producto.nombre, Number(item.producto.precio), item.cantidad, Number(item.producto.precio) * item.cantidad]))
async function checkout() { if (!auth.isAuthenticated) { await router.push({ path: '/ingresar', query: { redirect: '/tienda/carrito' } }); return } busy.value = true; try { const id = await ordersService.createOrder(cart.items.map((item) => ({ producto_id: item.producto.id, cantidad: item.cantidad }))); cart.clear(); toast.show('Pedido creado', `Tu pedido #${id} fue registrado.`, 'success'); await router.push('/tienda/mis-pedidos') } catch (error) { toast.show('No se pudo crear el pedido', getErrorMessage(error), 'error') } finally { busy.value = false } }
</script>
<template><main class="mx-auto max-w-6xl px-4 py-10 sm:px-6"><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 class="page-title">Tu carrito</h1><p class="page-copy">Revisa tus productos antes de confirmar.</p></div><ExportButtons title="Carrito de compra" file-name="carrito" :headers="['ID', 'Producto', 'Precio unitario (CRC)', 'Cantidad', 'Subtotal (CRC)']" :rows="exportRows" /></div><EmptyState v-if="!cart.items.length" class="mt-8" title="Tu carrito está vacío" message="Explora la tienda y agrega tus productos favoritos."><RouterLink to="/tienda" class="btn-primary"><ShoppingBag class="size-4" />Ver productos</RouterLink></EmptyState><div v-else class="mt-8 grid gap-8 lg:grid-cols-[1fr_360px]"><section class="space-y-4"><article v-for="item in cart.items" :key="item.producto.id" class="card flex gap-4 p-4"><div class="size-24 shrink-0 overflow-hidden rounded-xl bg-slate-100"><img v-if="item.producto.imagen_url" :src="item.producto.imagen_url" :alt="item.producto.nombre" class="size-full object-cover" /></div><div class="min-w-0 flex-1"><div class="flex justify-between gap-3"><div><h2 class="font-bold text-ink">{{ item.producto.nombre }}</h2><p class="text-sm text-slate-500">{{ formatCurrency(item.producto.precio) }} c/u</p></div><button class="text-slate-400 hover:text-red-600" aria-label="Eliminar" @click="cart.remove(item.producto.id)"><Trash2 class="size-5" /></button></div><div class="mt-4 flex items-center justify-between"><div class="flex items-center rounded-xl border border-slate-200"><button class="p-2" @click="cart.setQuantity(item.producto.id, item.cantidad - 1)"><Minus class="size-4" /></button><span class="w-9 text-center font-semibold">{{ item.cantidad }}</span><button class="p-2" @click="cart.setQuantity(item.producto.id, item.cantidad + 1)"><Plus class="size-4" /></button></div><strong>{{ formatCurrency(Number(item.producto.precio) * item.cantidad) }}</strong></div></div></article></section><aside class="card h-fit p-6"><h2 class="text-xl font-bold text-ink">Resumen</h2><div class="mt-5 space-y-3"><div class="flex justify-between text-slate-600"><span>Productos</span><span>{{ cart.count }}</span></div><div class="flex justify-between text-slate-600"><span>Envío</span><span>Por coordinar</span></div><div class="border-t border-slate-200 pt-4"><div class="flex justify-between text-xl font-bold text-ink"><span>Total</span><span>{{ formatCurrency(cart.total) }}</span></div></div></div><button class="btn-primary mt-6 w-full" :disabled="busy" @click="checkout">{{ auth.isAuthenticated ? 'Confirmar pedido' : 'Ingresar para comprar' }}</button><p class="mt-3 text-center text-sm text-slate-500">El inventario se valida al confirmar.</p></aside></div></main></template>
